window.__posterData({"id": "erik-bjelke-blomqvist", "name": "Erik Bjelke Blomqvist", "folder": "Week3_Poster_ErikBjelkeBlomqvist", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// ---------- Konstanter ----------\nconst CANVAS_WIDTH = 600;\nconst CANVAS_HEIGHT = 800;\nconst CENTER_X = 300;\n\nconst BLUR_AMOUNT = 10;\n\nconst CIRCLE_Y = 700;\nconst CIRCLE_SIZE = 20;\n\nconst TEXT_OUTLINE = 3; // används både som stroke-färg och strokeWeight\nconst TITLE_SIZE = 120;\nconst SUBTITLE_SIZE = 40;\n\nconst MOUSE_CIRCLE_SIZE = 20;\nconst MOUSE_JITTER = 38;\n\nconst PULSE_SPEED = 0.15;    // hur snabbt cirklarna pulserar\nconst PULSE_AMOUNT = 8;      // hur mycket cirklarna växer och krymper\nconst FLAMES_PER_FRAME = 2;  // nya lågor per cirkel och bildruta\n\nconst LASER_ORIGINS_X = [0, 300, 600]; // var lasrarna startar längs övre kanten\nconst LASER_LENGTH = 1500;             // tillräckligt långt för att gå utanför canvasen\nconst LASER_EASING = 0.06;             // hur mjukt lasrarna följer sitt mål (0-1)\n\n// ---------- Variabler ----------\nlet img;  // variabel för bilden\nlet font; // variabel för typsnittet\n\nconst skull = { x: 300, y: 450, size: 100, emoji: '💀' }; // kod från p5, variabel för objekt\n\nconst xCoordinates = [150, 300, 450]; // kod från p5 om for loop, variabel med koordinater för varje cirkel\n\nlet flames = []; // lista med alla lågor som just nu brinner\n\nlet laserTarget = { x: 300, y: 600 }; // punkten som lasrarna siktar mot\n\n// ---------- p5 ----------\nasync function setup() {\n  createCanvas(CANVAS_WIDTH, CANVAS_HEIGHT);\n  img = await loadImage('image.jpg');  // laddar in bildfilen\n  font = await loadFont('PirataOne-Regular.ttf');  // laddar in typsnittet\n}\n\nfunction draw() {\n  drawBackground();\n  drawLasers(); // bakom texten men framför bilden\n  drawCircleRow();\n  drawText('Exhibition', CENTER_X, 170, TITLE_SIZE);      // titel\n  drawText('By Rave D4ve', CENTER_X, 275, SUBTITLE_SIZE); // brödtext\n  drawSkull();\n\n  if (mouseIsPressed) { // kod från föreläsning med Austin, om musen trycks\n    drawMouseCircle();\n  }\n}\n\n// ---------- Hjälpfunktioner ----------\nfunction drawBackground() {\n  background(220);\n  image(img, 0, 0); // visar bilden\n  filter(BLUR, BLUR_AMOUNT); // effekt för bilden\n}\n\n// Lasrar från övre kanten. De svepar av sig själva, men siktar mot musen när den är över canvasen\nfunction drawLasers() {\n  updateLaserTarget();\n\n  push();\n  colorMode(HSB, 360, 100, 100, 100);\n  blendMode(ADD); // ljusa färger läggs ihop och ger en glödande effekt\n  strokeCap(ROUND);\n\n  for (let i = 0; i < LASER_ORIGINS_X.length; i += 1) {\n    const originX = LASER_ORIGINS_X[i];\n    const aimX = laserTarget.x + sin(frameCount * 0.03 + i * 2) * 80; // varje laser vinglar lite för sig\n    const angle = atan2(laserTarget.y, aimX - originX);\n    const endX = originX + cos(angle) * LASER_LENGTH;\n    const endY = sin(angle) * LASER_LENGTH;\n    const laserHue = (frameCount * 2 + i * 120) % 360; // färgerna växlar långsamt\n\n    stroke(laserHue, 90, 100, 20);\n    strokeWeight(14);\n    line(originX, 0, endX, endY); // mjuk glöd\n\n    stroke(laserHue, 40, 100, 90);\n    strokeWeight(2);\n    line(originX, 0, endX, endY); // skarp kärna\n  }\n  pop();\n  blendMode(BLEND); // återställer så att resten ritas som vanligt\n}\n\n// Flyttar målpunkten mjukt mot musen, eller svepar fram och tillbaka om musen inte är över canvasen\nfunction updateLaserTarget() {\n  const mouseOnCanvas = mouseX > 0 && mouseX < CANVAS_WIDTH && mouseY > 0 && mouseY < CANVAS_HEIGHT;\n\n  let goalX = CENTER_X + sin(frameCount * 0.02) * 300;\n  let goalY = CANVAS_HEIGHT * 0.75;\n  if (mouseOnCanvas) {\n    goalX = mouseX;\n    goalY = mouseY;\n  }\n\n  laserTarget.x = lerp(laserTarget.x, goalX, LASER_EASING);\n  laserTarget.y = lerp(laserTarget.y, goalY, LASER_EASING);\n}\n\nfunction drawCircleRow() {\n  if (mouseIsPressed) { // musen nedtryckt = cirklarna börjar brinna\n    spawnFlames();\n  }\n  updateFlames();\n  drawFlames(); // lågorna ritas först så att cirklarna hamnar ovanpå\n\n  for (let i = 0; i < xCoordinates.length; i += 1) { // kod från p5, loopar igenom koordinat-listan\n    drawRaveCircle(xCoordinates[i], i);\n  }\n}\n\n// En pulserande cirkel med glöd. Färgen växlar hela tiden, men blir eldorange när musen trycks\nfunction drawRaveCircle(x, index) {\n  push(); // push/pop så att färginställningarna inte påverkar resten av skissen\n  noStroke();\n  colorMode(HSB, 360, 100, 100, 100);\n\n  const pulse = sin(frameCount * PULSE_SPEED + index * 2); // varje cirkel pulserar lite förskjutet\n  const size = CIRCLE_SIZE + pulse * PULSE_AMOUNT;\n  const circleHue = mouseIsPressed ? 20 : (frameCount * 3 + index * 120) % 360;\n\n  fill(circleHue, 90, 100, 25);\n  circle(x, CIRCLE_Y, size * 2.2); // genomskinlig glöd runt cirkeln\n\n  fill(circleHue, 80, 100);\n  circle(x, CIRCLE_Y, size); // själva cirkeln\n  pop();\n}\n\n// Skapar nya lågor vid varje cirkel\nfunction spawnFlames() {\n  for (const x of xCoordinates) {\n    for (let n = 0; n < FLAMES_PER_FRAME; n += 1) {\n      flames.push({\n        x: x + random(-8, 8),\n        y: CIRCLE_Y,\n        vx: random(-0.6, 0.6),  // lite sidorörelse\n        vy: random(-4, -1.5),   // flyger uppåt\n        size: random(14, 24),\n        life: 1                 // 1 = nyss skapad, 0 = slocknad\n      });\n    }\n  }\n}\n\n// Flyttar lågorna, gör dem mindre och tar bort de som slocknat\nfunction updateFlames() {\n  for (const flame of flames) {\n    flame.x += flame.vx;\n    flame.y += flame.vy;\n    flame.size *= 0.97;\n    flame.life -= 0.02;\n  }\n  flames = flames.filter((flame) => flame.life > 0);\n}\n\n// Ritar lågorna: gula när de är nya, röda och genomskinliga när de slocknar\nfunction drawFlames() {\n  push();\n  noStroke();\n  blendMode(ADD); // ljusa färger läggs ihop och ger en glödande effekt\n  for (const flame of flames) {\n    fill(255, 40 + 180 * flame.life, 0, 200 * flame.life);\n    circle(flame.x, flame.y, flame.size);\n  }\n  pop();\n  blendMode(BLEND); // återställer så att resten ritas som vanligt\n}\n\n// Gemensamma egenskaper för titel och brödtext, bara text, position och storlek skiljer\nfunction drawText(content, x, y, size) {\n  textAlign(CENTER);\n  textFont(font);\n  stroke(TEXT_OUTLINE);\n  strokeWeight(TEXT_OUTLINE);\n  textSize(size);\n  fill('white');\n  text(content, x, y);\n}\n\nfunction drawSkull() {\n  textAlign(CENTER, CENTER); // kod från p5, egenskaper för objekt/emojin\n  textSize(skull.size); // storlek från variabeln\n  text(skull.emoji, skull.x, skull.y); // kod från p5, ritar ut emojin\n}\n\nfunction drawMouseCircle() {\n  fill(randomColorValue(), randomColorValue(), randomColorValue()); // färgval med random\n  strokeWeight(3); // outline\n  circle(\n    mouseX + random() * MOUSE_JITTER,\n    mouseY + random() * MOUSE_JITTER,\n    MOUSE_CIRCLE_SIZE\n  ); // cirkel med förskjutning\n}\n\n// Slumpmässigt värde mellan 100 och 150\nfunction randomColorValue() {\n  return random() * 50 + 100;\n}\n\n// // Steg 1. Den nya koden är justerad i Claude AI-verktyg och fungerar likadant som den gjorde innan efter ändringen. AI:n har dock lagt till cirka 40 nya rader kod och gjort den mer avancerad än den ursprungliga koden, vilket förvånade mig eftersom jag trodde den skulle göra den kortare och mer effektiv. Enligt mig själv tycker jag att den nu är svårare att läsa på grund av att det är fler rader med kod och att det känns som den gjort allt mycket mer komplicerat. Det är nu en helt annan struktur på koden då den  har använt fler funktioner än vad jag gjorde och använder många const i början av koden. Den har även sparat mina egna kommentarer men lägger även till nya som förklarar vad AI:ns kod gör, vilket är bra för att lära sig.\n\n// Steg 2. Prompt: Nu vill jag du gör om funktionen med cirklarna längst ner i postern. jag vill ha en mer rave-känsla på dom så det blir mer interaktivt. Kanske eld-effekt att det brinner när man trycker ned musen och cirklarna brinner. \n\n// I designkritiken fick jag som förslag att göra min poster mer levande och att det skulle hända mer saker när man klickade ner musen. Nu efter ändringen med AI så är den mer levande och känns mer rejvig än innan. Enligt mig blev resultatet bättre än förväntat, jag trodde den skulle ha svårt att efterlikna eld i postern men det blev riktigt bra. Den fick även in blinkande lampor för en mer ravekänsla, där den dock tog eget initiativ och bestämde själv hur det skulle appliceras eftersom min beskrivning kring det kanske inte var så tydlig. Det blev dock bara ett positivt tillskott vilket passade vår givna uppgift. Postern är nu mycket mer levande samtidigt som det passar in i den visuella riktningen i designen.\n\n// Steg 3. Jag använde prompten från instruktionen och lät den själv bestämma en förbättring i koden. I postern har AI:n lagt till laserstrålar som följer när musen rör på sig och den har inte tagit bort något från de förra funktionerna, så allt ser ut som förra steget men med laserstrålar. Enligt mig passar inte laserstrålarna in i denna posterns design, jag har ett lite mörkare tema och lasern passar inte riktigt in. Det känns som två olika posters och visar på att AI:n behöver tydligare instruktioner och vägledning. För att vidare utveckla den nya funktionen och postern med AI:n, hade nya instruktioner som att göra lasern mer passande till de övriga elementen varit bra. En lösning hade kunnat vara att fortsätta med eld-elementen och följa den grafiska riktningen, nu känns den rörig och kräver mer utveckling. ", "assets": {"PirataOne-Regular.ttf": {"mime": "font/ttf", "b64": ""}, "image.jpg": {"mime": "image/webp", "b64": ""}}});
